import AppKit
import SwiftUI

/// Dogear logo images that build-app.sh copies into Contents/Resources (sources
/// in App/Resources, generated by dogear-brand-assets/build-platform-icons.py).
/// A bare `swift run` has no app bundle, so callers fall back to an SF Symbol.
enum BrandImages {
    static let menuBar: NSImage? = {
        guard let image = Bundle.main.image(forResource: "MenuBarIcon") else { return nil }
        image.isTemplate = true // macOS tints it for light/dark menu bars
        return image
    }()
    static let mark = Bundle.main.image(forResource: "DogearMark")
    static let markReversed = Bundle.main.image(forResource: "DogearMarkReversed")
}

/// The full-color symbol, switching to the reversed artwork on dark backgrounds.
struct BrandMark: View {
    var height: CGFloat
    @Environment(\.colorScheme) private var colorScheme

    var body: some View {
        if let image = colorScheme == .dark ? BrandImages.markReversed : BrandImages.mark {
            Image(nsImage: image).resizable().interpolation(.high).scaledToFit().frame(height: height)
        } else {
            Image(systemName: "bookmark.square").font(.system(size: height)).foregroundStyle(.secondary)
        }
    }
}
